package nz.tate.worldgrid;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

/**
 * Launches a development client with this plugin loaded. Not a unit test -- it is the entry
 * point {@code ./gradlew run} uses, and it is the only way to verify the plugin in-game.
 */
public class WorldGridPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(WorldGridPlugin.class);
		RuneLite.main(args);
	}
}

package nz.tate.worldgrid;

import nz.tate.worldgrid.core.GridCell;
import nz.tate.worldgrid.core.GridMath;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Covers the boundary arithmetic the scene overlay uses to decide which grid lines
 * cross the loaded scene. The drawing itself needs a running client and is verified
 * in-game.
 */
public class SceneGridOverlayTest
{
	@Test
	public void findsTheFirstBoundaryAtOrAfterAPoint()
	{
		// Anchor itself is a boundary.
		assertEquals(1000, GridMath.firstBoundaryAtOrAfter(1000, 1000, 64));

		// One past a boundary rolls forward to the next.
		assertEquals(1064, GridMath.firstBoundaryAtOrAfter(1001, 1000, 64));

		// Exactly on the next boundary stays put.
		assertEquals(1064, GridMath.firstBoundaryAtOrAfter(1064, 1000, 64));
	}

	@Test
	public void worksBelowTheAnchor()
	{
		// Plain division truncates toward zero here and would return a boundary that
		// sits before the requested point.
		assertEquals(936, GridMath.firstBoundaryAtOrAfter(900, 1000, 64));
		assertEquals(872, GridMath.firstBoundaryAtOrAfter(872, 1000, 64));
	}

	@Test
	public void resultIsAlwaysOnTheGridAndNotBeforeTheStart()
	{
		int anchor = 768;
		for (int size : new int[]{1, 22, 63, 64, 256})
		{
			for (int from = 700; from < 1400; from++)
			{
				int boundary = GridMath.firstBoundaryAtOrAfter(from, anchor, size);
				assertTrue("not before start", boundary >= from);
				assertTrue("less than one cell past", boundary < from + size);
				assertEquals("on the grid", 0, Math.floorMod(boundary - anchor, size));
			}
		}
	}

	@Test
	public void compassLabelsSitOnTheCorrectEdges()
	{
		GridCell cell = new GridCell(10, 10, 0);
		int size = 64;

		int[] north = SceneGridOverlay.compassLabelPoint(cell, size, 'N');
		int[] south = SceneGridOverlay.compassLabelPoint(cell, size, 'S');
		int[] east = SceneGridOverlay.compassLabelPoint(cell, size, 'E');
		int[] west = SceneGridOverlay.compassLabelPoint(cell, size, 'W');

		// North is larger y, east is larger x. These are world directions, which is
		// what keeps the labels correct as the camera rotates.
		assertTrue("north is above south", north[1] > south[1]);
		assertTrue("east is right of west", east[0] > west[0]);

		// Opposite pairs share the other axis, so they line up across the square.
		assertEquals(north[0], south[0]);
		assertEquals(east[1], west[1]);
	}

	@Test
	public void compassLabelsStayInsideTheirCell()
	{
		int size = 64;
		GridCell cell = new GridCell(10, 10, 0);

		for (char direction : new char[]{'N', 'S', 'E', 'W'})
		{
			int[] point = SceneGridOverlay.compassLabelPoint(cell, size, direction);
			assertEquals("label " + direction + " belongs to its own cell",
				cell, GridMath.toCell(point[0], point[1], 0, size));
		}
	}
}

package nz.tate.worldgrid;

import nz.tate.worldgrid.core.SavedLocation;
import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class LocationDisplayTest
{
	private static final SavedLocation LUMBRIDGE =
		new SavedLocation("Lumbridge", 3222, 3218, 0, false);

	@Test
	public void theReferenceComesFromTheViewersOwnGridSize()
	{
		assertEquals("W39", LocationDisplay.reference(LUMBRIDGE, 64));
	}

	@Test
	public void theSamePlaceReadsDifferentlyAtADifferentGridSize()
	{
		String atSixtyFour = LocationDisplay.reference(LUMBRIDGE, 64);
		String atThirtyTwo = LocationDisplay.reference(LUMBRIDGE, 32);

		assertEquals("W39", atSixtyFour);
		assertEquals(false, atSixtyFour.equals(atThirtyTwo));
	}

	@Test
	public void aPlaceOutsideTheGridReadsAsNoReference()
	{
		SavedLocation southWestOfTheAnchor = new SavedLocation("Nowhere", 0, 0, 0, false);

		assertEquals(LocationDisplay.NO_REFERENCE,
			LocationDisplay.reference(southWestOfTheAnchor, 64));
	}

	@Test
	public void aPinTooltipCarriesTheNameAndTheLiveReference()
	{
		assertEquals("Lumbridge (W39)", LocationDisplay.tooltip(LUMBRIDGE, 64));
	}
}

package nz.tate.worldgrid;

import nz.tate.worldgrid.core.LocationCodec;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class ImportMessagesTest
{
	@Test
	public void theExportOptionsShowTheirCounts()
	{
		assertEquals("All saved (30)", ImportMessages.exportOptionLabel(false, 30));
		assertEquals("Pinned only (4)", ImportMessages.exportOptionLabel(true, 4));
		assertEquals("Pinned only (0)", ImportMessages.exportOptionLabel(true, 0));
	}

	@Test
	public void theTwoExportsGetDifferentDefaultNames()
	{
		String all = ImportMessages.defaultExportFileName(false);
		String pinned = ImportMessages.defaultExportFileName(true);

		assertEquals("world-grid-locations.json", all);
		assertEquals("world-grid-pinned.json", pinned);
		assertTrue(!all.equals(pinned));
	}

	@Test
	public void anExportAlwaysEndsUpAsJson()
	{
		assertEquals("route.json", ImportMessages.ensureJsonName("route"));
		assertEquals("route.json", ImportMessages.ensureJsonName("route.json"));
		assertEquals("route.JSON", ImportMessages.ensureJsonName("route.JSON"));
	}

	@Test
	public void theImportDialogNamesBothCounts()
	{
		assertEquals("This file has 12 locations. You have 4 saved.",
			ImportMessages.importCounts(12, 4));
	}

	@Test
	public void asingleIncomingLocationReadsAsSingular()
	{
		assertEquals("This file has 1 location. You have 0 saved.",
			ImportMessages.importCounts(1, 0));
	}

	@Test
	public void anOrdinarySizedFileGetsNoCaution()
	{
		assertNull(ImportMessages.largeImportCaution(1));
		assertNull(ImportMessages.largeImportCaution(
			LocationCodec.LARGE_FILE_WARNING_THRESHOLD));
	}

	@Test
	public void aLargeFileIsCautionedAboutButNeverRefused()
	{
		String caution = ImportMessages.largeImportCaution(
			LocationCodec.LARGE_FILE_WARNING_THRESHOLD + 1);

		assertNotNull(caution);
		assertTrue(caution.contains("201"));
	}
}

package nz.tate.worldgrid.core;

import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class LocationCodecTest
{
	private LocationCodec codec;

	@Before
	public void setUp()
	{
		codec = new LocationCodec(new Gson());
	}

	@Test
	public void writesAndReadsBack()
	{
		List<SavedLocation> original = Arrays.asList(
			new SavedLocation("Wine of Zamorak", 3095, 3494, 0, true),
			new SavedLocation("Clan meet", 3222, 3218, 1, false));

		LocationReadResult result = codec.read(codec.write(original));

		assertTrue(result.isSuccess());
		assertEquals(original, result.getLocations());
	}

	@Test
	public void writesTheSchemaVersion()
	{
		String json = codec.write(new ArrayList<>());
		assertTrue(json.contains("\"version\""));
		assertTrue(json.contains("1"));
	}

	@Test
	public void writesThePinnedFlag()
	{
		// The flag travels in the file even though import always clears it, so the
		// format is complete and a reader can see what the author had lit up.
		String json = codec.write(Arrays.asList(
			new SavedLocation("Wine spot", 3095, 3494, 0, true)));
		assertTrue(json.contains("\"pinned\""));
		assertTrue(json.contains("true"));
	}

	@Test
	public void rejectsMalformedJson()
	{
		String[] bad = {
			"{",
			"not json at all",
			"{\"version\":1,\"locations\":[",
			"[1,2,3",
		};
		for (String json : bad)
		{
			LocationReadResult result = codec.read(json);
			assertFalse("should reject: " + json, result.isSuccess());
			assertNotNull(result.getError());
		}
	}

	@Test
	public void rejectsEmptyInput()
	{
		assertFalse(codec.read("").isSuccess());
		assertFalse(codec.read("   ").isSuccess());
		assertFalse(codec.read(null).isSuccess());
	}

	@Test
	public void readsAFileWithNoLocationsArray()
	{
		LocationReadResult result = codec.read("{\"version\":1}");
		assertTrue(result.isSuccess());
		assertTrue(result.getLocations().isEmpty());
	}

	@Test
	public void rejectsCoordinatesOutsideTheWorld()
	{
		assertFalse(codec.read(
			"{\"version\":1,\"locations\":[{\"label\":\"x\",\"x\":-1,\"y\":3000,\"plane\":0}]}")
			.isSuccess());
		assertFalse(codec.read(
			"{\"version\":1,\"locations\":[{\"label\":\"x\",\"x\":99999,\"y\":3000,\"plane\":0}]}")
			.isSuccess());
		assertFalse(codec.read(
			"{\"version\":1,\"locations\":[{\"label\":\"x\",\"x\":3000,\"y\":-5,\"plane\":0}]}")
			.isSuccess());
	}

	@Test
	public void rejectsImpossiblePlanes()
	{
		assertFalse(codec.read(
			"{\"version\":1,\"locations\":[{\"label\":\"x\",\"x\":3000,\"y\":3000,\"plane\":9}]}")
			.isSuccess());
		assertFalse(codec.read(
			"{\"version\":1,\"locations\":[{\"label\":\"x\",\"x\":3000,\"y\":3000,\"plane\":-1}]}")
			.isSuccess());
	}

	@Test
	public void rejectsEntriesWithNoName()
	{
		assertFalse(codec.read(
			"{\"version\":1,\"locations\":[{\"x\":3000,\"y\":3000,\"plane\":0}]}").isSuccess());
		assertFalse(codec.read(
			"{\"version\":1,\"locations\":[{\"label\":\"  \",\"x\":3000,\"y\":3000,\"plane\":0}]}")
			.isSuccess());
	}

	@Test
	public void rejectsAFileFromANewerSchema()
	{
		LocationReadResult result = codec.read("{\"version\":99,\"locations\":[]}");
		assertFalse(result.isSuccess());
		assertTrue(result.getError().contains("newer"));
	}

	@Test
	public void rejectsTheWholeFileWhenOneEntryIsBad()
	{
		// Validate before mutating anything: a partial import is the worst outcome.
		String json = "{\"version\":1,\"locations\":["
			+ "{\"label\":\"good\",\"x\":3000,\"y\":3000,\"plane\":0},"
			+ "{\"label\":\"bad\",\"x\":99999,\"y\":3000,\"plane\":0}]}";
		assertFalse(codec.read(json).isSuccess());
	}

	@Test
	public void warnsOnlyAboveTheThreshold()
	{
		assertFalse(LocationCodec.isLargeImport(200));
		assertTrue(LocationCodec.isLargeImport(201));
	}
}

package nz.tate.worldgrid.core;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class ImportPlanTest
{
	private static SavedLocation at(String label, int x, int y)
	{
		return new SavedLocation(label, x, y, 0, false);
	}

	@Test
	public void mergeAddsNewEntries()
	{
		List<SavedLocation> existing = Arrays.asList(at("mine", 3000, 3000));
		List<SavedLocation> incoming = Arrays.asList(at("theirs", 3100, 3100));

		ImportPlan plan = ImportPlan.create(existing, incoming, ImportPlan.Mode.MERGE);

		assertEquals(2, plan.getResult().size());
		assertEquals(1, plan.getAddedCount());
		assertEquals(0, plan.getSkippedCount());
	}

	@Test
	public void mergeKeepsTheExistingLabelOnACollision()
	{
		List<SavedLocation> existing = Arrays.asList(at("my wine spot", 3095, 3494));
		List<SavedLocation> incoming = Arrays.asList(at("Wine of Zamorak", 3095, 3494));

		ImportPlan plan = ImportPlan.create(existing, incoming, ImportPlan.Mode.MERGE);

		assertEquals(1, plan.getResult().size());
		assertEquals("my wine spot", plan.getResult().get(0).getLabel());
		assertEquals(0, plan.getAddedCount());
		assertEquals(1, plan.getSkippedCount());
	}

	@Test
	public void mergeNeverMutatesAnExistingEntry()
	{
		SavedLocation mine = new SavedLocation("mine", 3000, 3000, 0, true);
		ImportPlan plan = ImportPlan.create(
			Arrays.asList(mine),
			Arrays.asList(new SavedLocation("theirs", 3000, 3000, 0, false)),
			ImportPlan.Mode.MERGE);

		// Same object, pinned state and label untouched.
		assertEquals(mine, plan.getResult().get(0));
		assertTrue(plan.getResult().get(0).isPinned());
	}

	@Test
	public void identityIsTheCoordinateNotTheLabel()
	{
		List<SavedLocation> existing = Arrays.asList(at("a", 3000, 3000));

		// Same tile, different name: a duplicate.
		assertEquals(1, ImportPlan.create(existing, Arrays.asList(at("b", 3000, 3000)),
			ImportPlan.Mode.MERGE).getResult().size());

		// Same name, different tile: not a duplicate.
		assertEquals(2, ImportPlan.create(existing, Arrays.asList(at("a", 3001, 3000)),
			ImportPlan.Mode.MERGE).getResult().size());
	}

	@Test
	public void planeIsPartOfIdentity()
	{
		List<SavedLocation> existing = Arrays.asList(new SavedLocation("ground", 3000, 3000, 0, false));
		List<SavedLocation> incoming = Arrays.asList(new SavedLocation("upstairs", 3000, 3000, 1, false));

		assertEquals(2, ImportPlan.create(existing, incoming, ImportPlan.Mode.MERGE)
			.getResult().size());
	}

	@Test
	public void importedEntriesArriveUnpinned()
	{
		List<SavedLocation> incoming = Arrays.asList(
			new SavedLocation("theirs", 3100, 3100, 0, true));

		ImportPlan merged = ImportPlan.create(new ArrayList<>(), incoming, ImportPlan.Mode.MERGE);
		assertFalse(merged.getResult().get(0).isPinned());

		ImportPlan replaced = ImportPlan.create(new ArrayList<>(), incoming, ImportPlan.Mode.REPLACE);
		assertFalse(replaced.getResult().get(0).isPinned());
	}

	@Test
	public void replaceDiscardsEverythingExisting()
	{
		List<SavedLocation> existing = Arrays.asList(at("a", 3000, 3000), at("b", 3001, 3000));
		List<SavedLocation> incoming = Arrays.asList(at("c", 3100, 3100));

		ImportPlan plan = ImportPlan.create(existing, incoming, ImportPlan.Mode.REPLACE);

		assertEquals(1, plan.getResult().size());
		assertEquals("c", plan.getResult().get(0).getLabel());
		assertEquals(2, plan.getDiscardedCount());
	}

	@Test
	public void mergeWithAnEmptyFileChangesNothing()
	{
		List<SavedLocation> existing = Arrays.asList(at("a", 3000, 3000));
		ImportPlan plan = ImportPlan.create(existing, new ArrayList<>(), ImportPlan.Mode.MERGE);
		assertEquals(existing, plan.getResult());
		assertEquals(0, plan.getAddedCount());
	}

	@Test
	public void duplicatesInsideTheIncomingFileAreCollapsed()
	{
		List<SavedLocation> incoming = Arrays.asList(at("a", 3000, 3000), at("b", 3000, 3000));
		ImportPlan plan = ImportPlan.create(new ArrayList<>(), incoming, ImportPlan.Mode.MERGE);
		assertEquals(1, plan.getResult().size());
		assertEquals(1, plan.getSkippedCount());
	}

	@Test
	public void outcomeIsAlwaysReported()
	{
		ImportPlan allDuplicates = ImportPlan.create(
			Arrays.asList(at("a", 3000, 3000)),
			Arrays.asList(at("b", 3000, 3000)),
			ImportPlan.Mode.MERGE);

		// An import where everything collided must not read as a silent no-op.
		assertEquals("Imported 0 new, skipped 1 already present.",
			allDuplicates.describeOutcome());

		assertEquals("Imported 1 new.", ImportPlan.create(
			new ArrayList<>(), Arrays.asList(at("a", 3000, 3000)), ImportPlan.Mode.MERGE)
			.describeOutcome());
	}
}

package nz.tate.worldgrid.core;

import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertEquals;

/**
 * Pins landmark references against the anchor.
 *
 * <p>These are the tripwire. Changing GridAnchor renames every square in the world and
 * invalidates every reference anyone has saved or written down, so it must never happen
 * by accident -- these assertions turn that into a loud failure.
 */
public class LandmarkReferenceTest
{
	private static final int SIZE = 64;

	private static void assertReference(String expected, int x, int y)
	{
		assertEquals(expected, GridRefFormatter.format(GridMath.toCell(x, y, 0, SIZE)));
	}

	@Test
	public void lumbridge()
	{
		assertReference("W39", 3222, 3218);
	}

	@Test
	public void varrockSquare()
	{
		assertReference("Z39", 3213, 3428);
	}

	@Test
	public void grandExchange()
	{
		assertReference("AA38", 3165, 3489);
	}

	@Test
	public void falador()
	{
		assertReference("Y35", 2965, 3380);
	}

	@Test
	public void edgeville()
	{
		assertReference("AA37", 3087, 3500);
	}

	@Test
	public void kourendCastle()
	{
		assertReference("AD14", 1628, 3673);
	}

	@Test
	public void southernSailingContentIsNameable()
	{
		// Sailing pushed the surface south of the old anchor, which made these points
		// produce a negative row index -- unrepresentable, so literally unnameable.
		assertReference("H29", 2567, 2295);
		assertReference("G41", 3357, 2203);
	}

	@Test
	public void theSouthWestMostSurfaceSquareIsInsideTheGrid()
	{
		GridCell corner = GridMath.toCell(960, 2048, 0, SIZE);
		assertFalse(corner.isNegative());
		assertReference("E4", 960, 2048);
	}

	@Test
	public void theNorthernOceanBandIsInsideTheGrid()
	{
		// The surface now reaches y=4223, above Constants.OVERWORLD_MAX_Y (4160). That
		// constant is stale, so the plugin never uses it as a bound.
		assertFalse(GridMath.toCell(3000, 4223, 0, SIZE).isNegative());
	}
}

package nz.tate.worldgrid.core;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Saved locations store coordinates and recompute the reference on display, so the
 * formatter and parser must be exact inverses. If they ever drift, a shared file starts
 * pointing somewhere other than where its author stood.
 */
public class GridRefRoundTripTest
{
	private static final int[] SIZES = {1, 22, 63, 64, 100, 256};

	@Test
	public void formatThenParseReturnsTheSameCellAcrossTheWorld()
	{
		for (int size : SIZES)
		{
			for (int x = GridAnchor.ANCHOR_X; x <= GridAnchor.WORLD_MAX; x += 337)
			{
				for (int y = GridAnchor.ANCHOR_Y; y <= GridAnchor.WORLD_MAX; y += 337)
				{
					GridCell original = GridMath.toCell(x, y, 0, size);
					String reference = GridRefFormatter.format(original);
					assertTrue("no reference for " + x + "," + y, reference != null);

					GridRefParseResult parsed = GridRefParser.parse(reference, size);
					assertTrue(reference + " at size " + size + " should parse", parsed.isSuccess());
					assertEquals(reference + " at size " + size, original, parsed.getCell());
				}
			}
		}
	}

	@Test
	public void roundTripHoldsForEveryPlane()
	{
		for (int plane = 0; plane <= 3; plane++)
		{
			GridCell original = GridMath.toCell(3222, 3218, plane, 64);
			String reference = GridRefFormatter.format(original);
			assertEquals(original, GridRefParser.parse(reference, 64).getCell());
		}
	}

	@Test
	public void parsedCellOriginLandsBackInsideTheSameCell()
	{
		// Parsing yields a square, not a tile. Converting the square's origin back must
		// return the same square, or a searched reference would pin the wrong place.
		for (int size : SIZES)
		{
			GridRefParseResult parsed = GridRefParser.parse("L35", size);
			if (!parsed.isSuccess())
			{
				continue;
			}
			GridCell cell = parsed.getCell();
			int x = GridMath.originX(cell, size);
			int y = GridMath.originY(cell, size);
			assertEquals(cell, GridMath.toCell(x, y, 0, size));

			int cx = GridMath.centreX(cell, size);
			int cy = GridMath.centreY(cell, size);
			assertEquals(cell, GridMath.toCell(cx, cy, 0, size));
		}
	}
}

package nz.tate.worldgrid.core;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class GridRefParserTest
{
	private static final int SIZE = 64;

	@Test
	public void parsesASimpleReference()
	{
		GridRefParseResult result = GridRefParser.parse("L35", SIZE);
		assertTrue(result.isSuccess());
		assertEquals(11, result.getCell().getRow());
		assertEquals(34, result.getCell().getColumn());
		assertEquals(0, result.getCell().getPlane());
	}

	@Test
	public void isCaseInsensitive()
	{
		assertEquals(
			GridRefParser.parse("L35", SIZE).getCell(),
			GridRefParser.parse("l35", SIZE).getCell());
	}

	@Test
	public void toleratesSurroundingAndInternalSpaces()
	{
		assertEquals(
			GridRefParser.parse("L35", SIZE).getCell(),
			GridRefParser.parse("  l 35 ", SIZE).getCell());
	}

	@Test
	public void parsesMultiLetterRows()
	{
		GridRefParseResult result = GridRefParser.parse("GA12", SIZE);
		assertTrue(result.isSuccess());
		assertEquals(GridRefFormatter.fromLetters("GA"), result.getCell().getRow());
		assertEquals(11, result.getCell().getColumn());
	}

	@Test
	public void parsesThePlaneSuffix()
	{
		assertEquals(2, GridRefParser.parse("L35+2", SIZE).getCell().getPlane());
	}

	@Test
	public void rejectsEmptyInput()
	{
		assertEquals(GridRefParseResult.Failure.EMPTY, GridRefParser.parse("", SIZE).getFailure());
		assertEquals(GridRefParseResult.Failure.EMPTY, GridRefParser.parse("   ", SIZE).getFailure());
		assertEquals(GridRefParseResult.Failure.EMPTY, GridRefParser.parse(null, SIZE).getFailure());
	}

	@Test
	public void rejectsMalformedInput()
	{
		String[] bad = {"35L", "L", "35", "L35+", "L-35", "!!", "L35+2+2", "L35x"};
		for (String input : bad)
		{
			GridRefParseResult result = GridRefParser.parse(input, SIZE);
			assertFalse("should reject " + input, result.isSuccess());
		}
	}

	@Test
	public void rejectsPlaneOutsideOneToThree()
	{
		assertEquals(
			GridRefParseResult.Failure.PLANE_OUT_OF_RANGE,
			GridRefParser.parse("L35+0", SIZE).getFailure());
		assertEquals(
			GridRefParseResult.Failure.PLANE_OUT_OF_RANGE,
			GridRefParser.parse("L35+4", SIZE).getFailure());
	}

	@Test
	public void rejectsColumnZero()
	{
		assertEquals(
			GridRefParseResult.Failure.COLUMN_OUT_OF_RANGE,
			GridRefParser.parse("L0", SIZE).getFailure());
	}

	@Test
	public void rejectsReferencesOutsideTheWorld()
	{
		assertEquals(
			GridRefParseResult.Failure.OUTSIDE_WORLD,
			GridRefParser.parse("L9999", SIZE).getFailure());
		assertEquals(
			GridRefParseResult.Failure.OUTSIDE_WORLD,
			GridRefParser.parse("ZZZ1", SIZE).getFailure());
	}

	@Test
	public void hugeInputDoesNotOverflowIntoAValidCell()
	{
		// A column large enough to wrap a 32-bit int must be refused, not silently
		// folded back into the playable world.
		GridRefParseResult result = GridRefParser.parse("A999999999999", SIZE);
		assertFalse(result.isSuccess());
	}

	@Test
	public void everyFailureCarriesAMessage()
	{
		String[] bad = {"", "35L", "L0", "L35+9", "L9999"};
		for (String input : bad)
		{
			assertNotNull("needs a message: " + input, GridRefParser.parse(input, SIZE).getMessage());
		}
	}
}

package nz.tate.worldgrid.core;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class GridRefFormatterTest
{
