package nz.tate.worldgrid;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;

/**
 * The two map pin images.
 *
 * <p>Saved and searched pins must be told apart at a glance -- "is this saved yet?" is
 * otherwise unanswerable -- so they differ in both shape and colour. They are drawn once
 * at class load rather than shipped as files, since they are a circle and a diamond.
 */
final class PinIcons
{
	private static final int SIZE = 13;

	/** Solid cyan disc: a place already in your library. */
	static final BufferedImage SAVED = drawDisc();

	/** Hollow yellow diamond: a searched reference, not saved yet. */
	static final BufferedImage SEARCH = drawDiamond();

	private PinIcons()
	{
	}

	private static BufferedImage drawDisc()
	{
		BufferedImage image = blank();
		Graphics2D graphics = start(image);
		graphics.setColor(new Color(0, 190, 240));
		graphics.fillOval(1, 1, SIZE - 3, SIZE - 3);
		graphics.setColor(Color.BLACK);
		graphics.drawOval(1, 1, SIZE - 3, SIZE - 3);
		graphics.dispose();
		return image;
	}

	private static BufferedImage drawDiamond()
	{
		BufferedImage image = blank();
		Graphics2D graphics = start(image);
		int mid = SIZE / 2;
		int[] x = {mid, SIZE - 2, mid, 1};
		int[] y = {1, mid, SIZE - 2, mid};

		graphics.setColor(new Color(0, 0, 0, 160));
		graphics.fillPolygon(x, y, 4);
		graphics.setColor(new Color(255, 210, 60));
		graphics.setStroke(new BasicStroke(2f));
		graphics.drawPolygon(x, y, 4);
		graphics.dispose();
		return image;
	}

	private static BufferedImage blank()
	{
		return new BufferedImage(SIZE, SIZE, BufferedImage.TYPE_INT_ARGB);
	}

	private static Graphics2D start(BufferedImage image)
	{
		Graphics2D graphics = image.createGraphics();
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING,
			RenderingHints.VALUE_ANTIALIAS_ON);
		return graphics;
	}
}

package nz.tate.worldgrid;

import java.awt.BasicStroke;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Shape;
import java.awt.Stroke;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.worldmap.WorldMap;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import nz.tate.worldgrid.core.GridAnchor;
import nz.tate.worldgrid.core.GridCell;
import nz.tate.worldgrid.core.GridMath;
import nz.tate.worldgrid.core.GridRefFormatter;

/**
 * Draws the grid over the world map.
 *
 * <p>Unlike the scene overlay, labelling many squares at once is the point here -- the
 * map is where you look up someone else's reference.
 */
public class WorldMapGridOverlay extends Overlay
{
	/**
	 * Below this many pixels per square the lines sit on top of each other and the map
	 * becomes unreadable, so the grid is not drawn at all.
	 */
	private static final int MIN_PIXELS_PER_CELL = 3;

	/** Labels need more room than lines, so they appear only once squares are big enough. */
	private static final int MIN_PIXELS_FOR_LABEL = 30;

	private final Client client;
	private final WorldGridConfig config;

	@Inject
	WorldMapGridOverlay(Client client, WorldGridConfig config)
	{
		this.client = client;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.MANUAL);
		drawAfterLayer(InterfaceID.Worldmap.MAP_CONTAINER);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.drawOnWorldMap())
		{
			return null;
		}

		WorldMap worldMap = client.getWorldMap();
		Widget mapView = client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER);
		if (worldMap == null || mapView == null || mapView.isHidden())
		{
			return null;
		}

		int gridSize = config.gridSize();
		float pixelsPerTile = worldMap.getWorldMapZoom();
		float pixelsPerCell = pixelsPerTile * gridSize;
		if (pixelsPerCell < MIN_PIXELS_PER_CELL)
		{
			return null;
		}

		Rectangle bounds = mapView.getBounds();
		Point centreTile = worldMap.getWorldMapPosition();
		if (bounds == null || centreTile == null)
		{
			return null;
		}

		Shape previousClip = graphics.getClip();
		Stroke previousStroke = graphics.getStroke();
		graphics.setClip(bounds);
		graphics.setColor(config.gridColour());
		graphics.setStroke(new BasicStroke(config.lineThickness()));

		drawGrid(graphics, bounds, centreTile, pixelsPerTile, gridSize, pixelsPerCell);

		graphics.setStroke(previousStroke);
		graphics.setClip(previousClip);
		return null;
	}

	private void drawGrid(Graphics2D graphics, Rectangle bounds, Point centreTile,
		float pixelsPerTile, int gridSize, float pixelsPerCell)
	{
		// Tiles visible either side of the centre, rounded outward so partly visible
		// squares still get their lines.
		int halfTilesAcross = (int) (bounds.width / pixelsPerTile / 2) + gridSize;
		int halfTilesDown = (int) (bounds.height / pixelsPerTile / 2) + gridSize;

		int minWorldX = centreTile.getX() - halfTilesAcross;
		int maxWorldX = centreTile.getX() + halfTilesAcross;
		int minWorldY = centreTile.getY() - halfTilesDown;
		int maxWorldY = centreTile.getY() + halfTilesDown;

		boolean drawLabels = pixelsPerCell >= MIN_PIXELS_FOR_LABEL;

		for (int worldX = GridMath.firstBoundaryAtOrAfter(minWorldX, GridAnchor.ANCHOR_X, gridSize);
			worldX <= maxWorldX; worldX += gridSize)
		{
			int screenX = toScreenX(bounds, centreTile, pixelsPerTile, worldX);
			graphics.drawLine(screenX, bounds.y, screenX, bounds.y + bounds.height);
		}

		for (int worldY = GridMath.firstBoundaryAtOrAfter(minWorldY, GridAnchor.ANCHOR_Y, gridSize);
			worldY <= maxWorldY; worldY += gridSize)
		{
			int screenY = toScreenY(bounds, centreTile, pixelsPerTile, worldY);
			graphics.drawLine(bounds.x, screenY, bounds.x + bounds.width, screenY);
		}

		if (drawLabels)
		{
			drawLabels(graphics, bounds, centreTile, pixelsPerTile, gridSize,
				minWorldX, maxWorldX, minWorldY, maxWorldY);
		}
	}

	private void drawLabels(Graphics2D graphics, Rectangle bounds, Point centreTile,
		float pixelsPerTile, int gridSize, int minWorldX, int maxWorldX, int minWorldY, int maxWorldY)
	{
		for (int worldX = GridMath.firstBoundaryAtOrAfter(minWorldX, GridAnchor.ANCHOR_X, gridSize);
			worldX <= maxWorldX; worldX += gridSize)
		{
			for (int worldY = GridMath.firstBoundaryAtOrAfter(minWorldY, GridAnchor.ANCHOR_Y, gridSize);
				worldY <= maxWorldY; worldY += gridSize)
			{
				GridCell cell = GridMath.toCell(worldX, worldY, 0, gridSize);
				String reference = GridRefFormatter.format(cell);
				if (reference == null)
				{
					continue;
				}

				// Sits just inside the square's south-west corner on screen, which is
				// the top-left going down the map.
				int screenX = toScreenX(bounds, centreTile, pixelsPerTile, worldX) + 2;
				int screenY = toScreenY(bounds, centreTile, pixelsPerTile, worldY + gridSize) + 12;
				if (bounds.contains(screenX, screenY))
				{
					graphics.drawString(reference, screenX, screenY);
				}
			}
		}
	}

	private static int toScreenX(Rectangle bounds, Point centreTile, float pixelsPerTile, int worldX)
	{
		return (int) (bounds.x + bounds.width / 2.0 + (worldX - centreTile.getX()) * pixelsPerTile);
	}

	private static int toScreenY(Rectangle bounds, Point centreTile, float pixelsPerTile, int worldY)
	{
		// Screen y grows downward while world y grows north, so the sign flips.
		return (int) (bounds.y + bounds.height / 2.0 - (worldY - centreTile.getY()) * pixelsPerTile);
	}
}

package nz.tate.worldgrid;

import java.awt.BasicStroke;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Stroke;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Constants;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import nz.tate.worldgrid.core.GridAnchor;
import nz.tate.worldgrid.core.GridCell;
import nz.tate.worldgrid.core.GridMath;
import nz.tate.worldgrid.core.GridRefFormatter;

/**
 * Draws the grid over the game world and labels the square the player is standing in.
 *
 * <p>Only the loaded scene is considered, never the whole world.
 */
public class SceneGridOverlay extends Overlay
{
	private static final int HALF_TILE = Perspective.LOCAL_TILE_SIZE / 2;
	private static final int SCENE_RADIUS = Constants.SCENE_SIZE / 2;

	/**
	 * Most boundary lines drawn per axis. Each line costs one projection per tile it
	 * spans, so without this a grid size of 1 would ask for over twenty thousand
	 * projections every frame. When the limit bites, the grid is drawn closer in around
	 * the player rather than being dropped entirely.
	 */
	private static final int MAX_LINES_PER_AXIS = 24;

	private static final char[] DIRECTIONS = {'N', 'S', 'E', 'W'};

	private final Client client;
	private final WorldGridPlugin plugin;
	private final WorldGridConfig config;

	@Inject
	SceneGridOverlay(Client client, WorldGridPlugin plugin, WorldGridConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.drawInScene())
		{
			return null;
		}

		GridCell cell = plugin.currentCell();
		if (cell == null)
		{
			// In an instance the coordinates do not match where the player appears to
			// be, so drawing a grid there would be actively misleading.
			return null;
		}

		Player player = client.getLocalPlayer();
		if (player == null)
		{
			return null;
		}

		int gridSize = config.gridSize();
		WorldPoint location = player.getWorldLocation();
		int radius = drawRadius(gridSize);

		Stroke previousStroke = graphics.getStroke();
		graphics.setColor(config.gridColour());
		graphics.setStroke(new BasicStroke(config.lineThickness()));

		int minX = location.getX() - radius;
		int maxX = location.getX() + radius;
		int minY = location.getY() - radius;
		int maxY = location.getY() + radius;

		for (int x = GridMath.firstBoundaryAtOrAfter(minX, GridAnchor.ANCHOR_X, gridSize); x <= maxX; x += gridSize)
		{
			drawBoundary(graphics, x, minY, maxY, true);
		}
		for (int y = GridMath.firstBoundaryAtOrAfter(minY, GridAnchor.ANCHOR_Y, gridSize); y <= maxY; y += gridSize)
		{
			drawBoundary(graphics, y, minX, maxX, false);
		}

		graphics.setStroke(previousStroke);
		drawCellLabel(graphics, cell, gridSize);
		drawCompassLabels(graphics, cell, gridSize);
		return null;
	}

	/**
	 * Labels the four edges of the current square with the compass direction they face.
	 *
	 * <p>Each label's position is worked out in world coordinates -- north is simply
	 * larger y -- and only then projected to the screen. Because the projection already
	 * accounts for where the camera is, the labels follow the world as it rotates
	 * instead of being pinned to the screen. That is the whole point of them: they tell
	 * you which way is north.
	 */
	private void drawCompassLabels(Graphics2D graphics, GridCell cell, int gridSize)
	{
		for (char direction : DIRECTIONS)
		{
			int[] point = compassLabelPoint(cell, gridSize, direction);
			drawWorldText(graphics, String.valueOf(direction), point[0], point[1]);
		}
	}

	private void drawWorldText(Graphics2D graphics, String text, int worldX, int worldY)
	{
		LocalPoint local = LocalPoint.fromWorld(client, worldX, worldY);
		if (local == null)
		{
			return;
		}

		Point canvas = Perspective.getCanvasTextLocation(client, graphics, local, text, 0);
		if (canvas != null)
		{
			OverlayUtil.renderTextLocation(graphics, canvas, text, config.gridColour());
		}
	}

	/**
	 * How far out to draw, in tiles. Normally the whole loaded scene, shrunk when a
	 * small grid size would otherwise put too many lines on screen.
	 */
	private static int drawRadius(int gridSize)
	{
		int affordable = gridSize * MAX_LINES_PER_AXIS / 2;
		return Math.min(SCENE_RADIUS, affordable);
	}

	/**
	 * Draws one boundary line. A vertical boundary runs north-south at a fixed world x;
	 * a horizontal one runs east-west at a fixed world y.
	 */
	private void drawBoundary(Graphics2D graphics, int fixed, int from, int to, boolean vertical)
	{
		Point previous = null;
		for (int along = from; along <= to; along++)
		{
			Point current = vertical
				? cornerToCanvas(fixed, along)
				: cornerToCanvas(along, fixed);

			// Either end may be off-screen or behind the camera, in which case that
			// segment simply is not drawn.
			if (previous != null && current != null)
			{
				graphics.drawLine(previous.getX(), previous.getY(), current.getX(), current.getY());
			}
			previous = current;
		}
	}

	/**
	 * Boundaries run along tile corners, but LocalPoint.fromWorld gives tile centres,
	 * so half a tile comes off each axis.
	 */
	private Point cornerToCanvas(int worldX, int worldY)
	{
		LocalPoint centre = LocalPoint.fromWorld(client, worldX, worldY);
		if (centre == null)
		{
			return null;
		}
		LocalPoint corner = new LocalPoint(centre.getX() - HALF_TILE, centre.getY() - HALF_TILE);
		return Perspective.localToCanvas(client, corner, client.getPlane());
	}

	private void drawCellLabel(Graphics2D graphics, GridCell cell, int gridSize)
	{
		String reference = GridRefFormatter.format(cell);
		if (reference == null)
		{
			return;
		}

		LocalPoint local = LocalPoint.fromWorld(client,
			GridMath.centreX(cell, gridSize), GridMath.centreY(cell, gridSize));
		if (local == null)
		{
			return;
		}

		Point canvas = Perspective.getCanvasTextLocation(client, graphics, local, reference, 0);
		if (canvas != null)
		{
			OverlayUtil.renderTextLocation(graphics, canvas, reference, config.gridColour());
		}
	}

	/** Edge midpoints of a cell, in world coordinates. Pure, so it is unit tested. */
	static int[] compassLabelPoint(GridCell cell, int gridSize, char direction)
	{
		int westX = GridMath.originX(cell, gridSize);
		int southY = GridMath.originY(cell, gridSize);
		int centreX = GridMath.centreX(cell, gridSize);
		int centreY = GridMath.centreY(cell, gridSize);

		switch (direction)
		{
			case 'N':
				return new int[]{centreX, southY + gridSize - 1};
			case 'S':
				return new int[]{centreX, southY};
			case 'E':
				return new int[]{westX + gridSize - 1, centreY};
			case 'W':
				return new int[]{westX, centreY};
			default:
				throw new IllegalArgumentException("Not a direction: " + direction);
		}
	}
}

package nz.tate.worldgrid;

import com.google.inject.Provides;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ImageUtil;
import nz.tate.worldgrid.core.GridCell;
import nz.tate.worldgrid.core.GridMath;
import nz.tate.worldgrid.core.GridRefFormatter;

@Slf4j
@PluginDescriptor(
	name = "World Grid",
	description = "A labelled grid over the world so players can name an exact location"
		+ " to each other",
	tags = {"grid", "coordinates", "location", "map", "navigation"}
)
public class WorldGridPlugin extends Plugin
{
	/**
	 * Shown instead of a reference inside an instance. Instanced regions report
	 * coordinates that do not correspond to where you appear to be, so any reference
	 * computed there would be confidently wrong.
	 */
	public static final String NO_REFERENCE = "—";

	@Inject
	private Client client;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private WorldGridConfig config;

	@Inject
	private GridRefHudOverlay hudOverlay;

	@Inject
	private SceneGridOverlay sceneGridOverlay;

	@Inject
	private WorldMapGridOverlay worldMapGridOverlay;

	@Inject
	private LocationRepository locationRepository;

	@Inject
	private PinManager pinManager;

	@Inject
	private GridSearch gridSearch;

	@Inject
	private EventBus eventBus;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private WorldGridPanel panel;

	private NavigationButton navigationButton;

	@Provides
	WorldGridConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(WorldGridConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(hudOverlay);
		overlayManager.add(sceneGridOverlay);
		overlayManager.add(worldMapGridOverlay);
		locationRepository.startUp();
		eventBus.register(gridSearch);

		navigationButton = NavigationButton.builder()
			.tooltip("World Grid")
			.icon(ImageUtil.loadImageResource(WorldGridPlugin.class, "panel_icon.png"))
			.priority(6)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navigationButton);
		log.debug("World Grid started");
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(hudOverlay);
		overlayManager.remove(sceneGridOverlay);
		overlayManager.remove(worldMapGridOverlay);
		clientToolbar.removeNavigation(navigationButton);
		navigationButton = null;
		eventBus.unregister(gridSearch);
		gridSearch.shutDown();
		locationRepository.shutDown();
		pinManager.shutDown();
		log.debug("World Grid stopped");
	}

	/**
	 * Grid size is a pure view setting, so changing it renames every saved location
	 * without touching the file.
	 */
	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (WorldGridConfig.GROUP.equals(event.getGroup()) && "gridSize".equals(event.getKey()))
		{
			SwingUtilities.invokeLater(() ->
			{
				panel.rebuild();
				pinManager.refresh();
			});
		}
	}

	/**
	 * @return the cell the player is standing in, or null in an instance or before the
	 * player has loaded
	 */
	public GridCell currentCell()
	{
		if (client.isInInstancedRegion())
		{
			return null;
		}

		Player player = client.getLocalPlayer();
		if (player == null)
		{
			return null;
		}

		WorldPoint location = player.getWorldLocation();
		if (location == null)
		{
			return null;
		}
		return GridMath.toCell(location.getX(), location.getY(), location.getPlane(),
			config.gridSize());
	}

	/**
	 * @return the reference to display, never null -- an em dash stands in wherever a
	 * real reference cannot be computed
	 */
	public String currentReference()
	{
		GridCell cell = currentCell();
		if (cell == null)
		{
			return NO_REFERENCE;
		}

		String reference = GridRefFormatter.format(cell);
		return reference == null ? NO_REFERENCE : reference;
	}
}

