import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.worldmap.WorldMap;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;
import nz.tate.worldgrid.core.SavedLocation;

/**
 * The saved-location library.
 *
 * <p>There is no search box here on purpose: searching lives on the world map's
 * right-click menu, so this panel is only ever a list of places you have kept.
 *
 * <p>Everything in this class runs on the Swing event thread. Reading the player's
 * position goes through {@link ClientThread}, and the answer comes back with
 * {@link SwingUtilities#invokeLater}.
 */
@Singleton
public class WorldGridPanel extends PluginPanel
{
	private final Client client;
	private final ClientThread clientThread;
	private final WorldGridConfig config;
	private final LocationRepository repository;
	private final ImportExport importExport;

	private final JPanel listPanel = new JPanel(new GridLayout(0, 1, 0, 5));
	private final JCheckBox selectAll = new JCheckBox("Select all");
	private final JButton deleteSelected = new JButton("Delete selected (0)");

	/**
	 * Transient view state. Rows are held by coordinate rather than by object, because
	 * pinning replaces the entry object while still meaning the same place. Never saved.
	 */
	private Set<String> selectedKeys = new LinkedHashSet<>();

	@Inject
	WorldGridPanel(Client client, ClientThread clientThread, WorldGridConfig config,
		LocationRepository repository, ImportExport importExport)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
		this.repository = repository;
		this.importExport = importExport;

		setLayout(new BorderLayout(0, 10));
		setBorder(new EmptyBorder(10, 10, 10, 10));
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		add(createHeader(), BorderLayout.NORTH);

		// The list sits at the top of a stretchy panel so short lists do not have their
		// rows spread down the whole panel.
		JPanel listHolder = new JPanel(new BorderLayout());
		listHolder.setBackground(ColorScheme.DARK_GRAY_COLOR);
		listPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		listHolder.add(listPanel, BorderLayout.NORTH);
		add(listHolder, BorderLayout.CENTER);

		repository.addListener(this::rebuild);
		rebuild();
	}

	private JPanel createHeader()
	{
		JPanel header = new JPanel(new GridLayout(0, 1, 0, 5));
		header.setBackground(ColorScheme.DARK_GRAY_COLOR);

		JLabel title = new JLabel("Saved locations");
		title.setFont(title.getFont().deriveFont(Font.BOLD));
		header.add(title);

		JButton saveCurrent = new JButton("Save current location");
		saveCurrent.setFocusPainted(false);
		saveCurrent.addActionListener(event -> saveCurrentLocation());
		header.add(saveCurrent);

		selectAll.setBackground(ColorScheme.DARK_GRAY_COLOR);
		selectAll.setFocusPainted(false);
		selectAll.addActionListener(event -> toggleSelectAll());
		header.add(selectAll);

		deleteSelected.setFocusPainted(false);
		deleteSelected.addActionListener(event -> deleteSelected());
		header.add(deleteSelected);

		JPanel transfer = new JPanel(new GridLayout(1, 2, 5, 0));
		transfer.setBackground(ColorScheme.DARK_GRAY_COLOR);

		JButton importButton = new JButton("Import");
		importButton.setFocusPainted(false);
		importButton.addActionListener(event ->
			importExport.startImport(this, this::clearSelection));
		transfer.add(importButton);

		JButton exportButton = new JButton("Export");
		exportButton.setFocusPainted(false);
		exportButton.addActionListener(event ->
			importExport.export(this, repository.getLocations()));
		transfer.add(exportButton);

		header.add(transfer);

		return header;
	}

	/** Rebuilds every row. Cheap enough for a list of this size and impossible to get stale. */
	void rebuild()
	{
		listPanel.removeAll();

		String error = repository.getLoadError();
		if (error != null)
		{
			listPanel.add(createMessage("Could not read your saved locations: " + error));
		}

		List<SavedLocation> locations = repository.getLocations();
		selectedKeys = LocationEdits.retainExisting(selectedKeys, locations);

		if (locations.isEmpty())
		{
			listPanel.add(createMessage("Nothing saved yet."));
		}
		else
		{
			int gridSize = config.gridSize();
			for (SavedLocation location : locations)
			{
				listPanel.add(createRow(location, gridSize));
			}
		}

		updateSelectionControls(locations);
		listPanel.revalidate();
		listPanel.repaint();
	}

	private JLabel createMessage(String text)
	{
		JLabel message = new JLabel("<html><body style='width:170px'>" + text + "</body></html>");
		message.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		return message;
	}

	private JPanel createRow(SavedLocation location, int gridSize)
	{
		JPanel row = new JPanel(new BorderLayout(4, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(new EmptyBorder(6, 8, 6, 4));

		JPanel text = new JPanel(new GridLayout(2, 1));
		text.setBackground(ColorScheme.DARKER_GRAY_COLOR);

		JLabel name = new JLabel(location.getLabel());
		name.setToolTipText(location.getLabel());
		text.add(name);

		JLabel reference = new JLabel(LocationDisplay.reference(location, gridSize));
		reference.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		text.add(reference);

		JCheckBox select = new JCheckBox();
		select.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		select.setToolTipText("Select for bulk delete");
		select.setSelected(selectedKeys.contains(LocationEdits.placeKey(location)));
		select.addActionListener(event -> setSelected(location, select.isSelected()));

		row.add(select, BorderLayout.WEST);
		row.add(text, BorderLayout.CENTER);
		row.add(createRowButtons(location), BorderLayout.EAST);
		return row;
	}

	private JPanel createRowButtons(SavedLocation location)
	{
		JPanel buttons = new JPanel(new FlowLayout(FlowLayout.RIGHT, 2, 0));
		buttons.setBackground(ColorScheme.DARKER_GRAY_COLOR);

		JButton pin = compactButton(location.isPinned() ? "Pinned" : "Pin",
			location.isPinned()
				? "Remove this location's world map pin"
				: "Show this location on the world map");
		// A lit background rather than a tick, so the pin never reads as a selection
		// checkbox sitting next to it.
		pin.setBackground(location.isPinned()
			? ColorScheme.BRAND_ORANGE
			: ColorScheme.DARK_GRAY_COLOR);
		pin.addActionListener(event -> togglePinned(location));
		buttons.add(pin);

		JButton showOnMap = compactButton("Map", "Centre the world map here");
		showOnMap.addActionListener(event -> showOnMap(location));
		buttons.add(showOnMap);

		JButton delete = compactButton("X", "Delete this location");
		delete.addActionListener(event -> deleteOne(location));
		buttons.add(delete);

		return buttons;
	}

	private JButton compactButton(String text, String tooltip)
	{
		JButton button = new JButton(text);
		button.setToolTipText(tooltip);
		button.setFocusPainted(false);
		button.setMargin(new Insets(2, 4, 2, 4));
		button.setPreferredSize(new Dimension(text.length() > 1 ? 8 + text.length() * 7 : 24, 22));
		return button;
	}

	private void setSelected(SavedLocation location, boolean selected)
	{
		String key = LocationEdits.placeKey(location);
		if (selected)
		{
			selectedKeys.add(key);
		}
		else
		{
			selectedKeys.remove(key);
		}
		updateSelectionControls(repository.getLocations());
	}

	private void toggleSelectAll()
	{
		if (selectAll.isSelected())
		{
			selectedKeys = LocationEdits.allKeys(repository.getLocations());
		}
		else
		{
			selectedKeys = new LinkedHashSet<>();
		}
		rebuild();
	}

	private void updateSelectionControls(List<SavedLocation> locations)
	{
		deleteSelected.setText("Delete selected (" + selectedKeys.size() + ")");
		deleteSelected.setEnabled(!selectedKeys.isEmpty());
		selectAll.setEnabled(!locations.isEmpty());
		selectAll.setSelected(!locations.isEmpty() && selectedKeys.size() == locations.size());
	}

	private void deleteSelected()
	{
		int count = selectedKeys.size();
		if (count == 0)
		{
			return;
		}

		if (LocationEdits.needsDeleteConfirmation(count)
			&& JOptionPane.showConfirmDialog(this,
				"Delete " + count + " saved locations?\n"
					+ "A backup of the current file is written first.",
				"Delete locations", JOptionPane.YES_NO_OPTION) != JOptionPane.YES_OPTION)
		{
			return;
		}

		repository.replaceAll(
			LocationEdits.withoutKeys(repository.getLocations(), selectedKeys), true);
		selectedKeys = new LinkedHashSet<>();
	}

	/** Selection is view state only, so closing the panel forgets it. */
	@Override
	public void onDeactivate()
	{
		clearSelection();
	}

	private void clearSelection()
	{
		selectedKeys = new LinkedHashSet<>();
		rebuild();
	}

	private void togglePinned(SavedLocation location)
	{
		repository.replaceAll(LocationEdits.withPinnedKey(repository.getLocations(),
			LocationEdits.placeKey(location), !location.isPinned()), false);
	}

	private void showOnMap(SavedLocation location)
	{
		WorldPoint target =
			new WorldPoint(location.getX(), location.getY(), location.getPlane());
		clientThread.invoke(() ->
		{
			WorldMap worldMap = client.getWorldMap();
			if (worldMap != null)
			{
				worldMap.setWorldMapPositionTarget(target);
			}
		});
	}

	private void deleteOne(SavedLocation location)
	{
		int choice = JOptionPane.showConfirmDialog(this,
			"Delete \"" + location.getLabel() + "\"?",
			"Delete location", JOptionPane.YES_NO_OPTION);
		if (choice != JOptionPane.YES_OPTION)
		{
			return;
		}

		repository.replaceAll(LocationEdits.withoutKeys(repository.getLocations(),
			Collections.singleton(LocationEdits.placeKey(location))), true);
	}

	/**
	 * Reads where the player is standing before asking for a name, so the entry records
	 * the spot you clicked from rather than wherever you drifted to while typing.
	 */
	private void saveCurrentLocation()
	{
		clientThread.invoke(() ->
		{
			final WorldPoint here = playerLocation();
			SwingUtilities.invokeLater(() -> promptAndSave(here));
		});
	}

	private WorldPoint playerLocation()
	{
		if (client.isInInstancedRegion())
		{
			return null;
		}

		Player player = client.getLocalPlayer();
		return player == null ? null : player.getWorldLocation();
	}

	private void promptAndSave(WorldPoint point)
	{
		if (point == null)
		{
			JOptionPane.showMessageDialog(this,
				"Your position is not available here. Instanced areas report coordinates"
					+ " that do not match where you are.",
				"Cannot save", JOptionPane.WARNING_MESSAGE);
			return;
		}

		String label = JOptionPane.showInputDialog(this, "Name for this location:",
			"Save location", JOptionPane.PLAIN_MESSAGE);
		SavedLocation saved = buildSaved(label, point);
		if (saved == null)
		{
			return;
		}

		if (LocationEdits.containsKey(repository.getLocations(), LocationEdits.placeKey(saved)))
		{
			JOptionPane.showMessageDialog(this, "That exact tile is already saved.",
				"Already saved", JOptionPane.INFORMATION_MESSAGE);
			return;
		}

		repository.replaceAll(LocationEdits.withAdded(repository.getLocations(), saved), false);
	}

	/** @return the entry to save, or null when the user cancelled or typed nothing usable */
	private SavedLocation buildSaved(String label, WorldPoint point)
	{
		String trimmed = LocationEdits.cleanLabel(label);
		if (trimmed == null)
		{
			return null;
		}

		return new SavedLocation(trimmed, point.getX(), point.getY(), point.getPlane(), false);
	}
}

package nz.tate.worldgrid;

import com.google.gson.Gson;
import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.time.Instant;
import java.time.ZoneId;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.RejectedExecutionException;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;
import nz.tate.worldgrid.core.LocationCodec;
import nz.tate.worldgrid.core.LocationReadResult;
import nz.tate.worldgrid.core.SavedLocation;

/**
 * Holds the saved locations and owns the file they live in.
 *
 * <p>Disk work never runs on the client thread. Reads and writes go to a single
 * background thread and the resulting list is published back on the Swing event thread,
 * which is where the panel and every edit live.
 *
 * <p>The in-memory list is always replaced wholesale by an unmodifiable copy rather than
 * mutated in place, so a reader on another thread can never see a half-applied edit.
 */
@Slf4j
@Singleton
public class LocationRepository
{
	private static final String DIRECTORY_NAME = "world-grid";
	private static final String FILE_NAME = "locations.json";

	private final LocationCodec codec;
	private final File directory;
	private final File workingFile;

	private final List<Runnable> listeners = new CopyOnWriteArrayList<>();

	private volatile List<SavedLocation> locations = Collections.emptyList();
	private volatile String loadError;

	private ExecutorService executor;
	private Future<?> pendingLoad;

	@Inject
	LocationRepository(Gson gson)
	{
		this.codec = new LocationCodec(gson);
		this.directory = new File(RuneLite.RUNELITE_DIR, DIRECTORY_NAME);
		this.workingFile = new File(directory, FILE_NAME);
	}

	/** Starts the worker and kicks off the initial read. Never blocks. */
	public void startUp()
	{
		executor = Executors.newSingleThreadExecutor();
		pendingLoad = executor.submit(this::readWorkingFile);
	}

	public void shutDown()
	{
		if (pendingLoad != null)
		{
			pendingLoad.cancel(true);
			pendingLoad = null;
		}
		if (executor != null)
		{
			executor.shutdownNow();
			executor = null;
		}
		// Listeners are not dropped: the panel and the pin manager register once, when
		// they are constructed, and outlive a stop-and-start of the plugin.
		locations = Collections.emptyList();
	}

	/** Called on the Swing event thread whenever the list changes. */
	public void addListener(Runnable listener)
	{
		listeners.add(listener);
	}

	public List<SavedLocation> getLocations()
	{
		return locations;
	}

	/** Why the working file could not be read, or null when all is well. */
	public String getLoadError()
	{
		return loadError;
	}

	public File getDirectory()
	{
		return directory;
	}

	/**
	 * Replaces the whole list and queues a write. Call from the Swing event thread.
	 *
	 * @param backupFirst true for destructive changes, so a mis-click stays recoverable
	 */
	public void replaceAll(List<SavedLocation> next, boolean backupFirst)
	{
		locations = Collections.unmodifiableList(next);
		notifyListeners();

		final String json = codec.write(locations);
		submit(() ->
		{
			if (backupFirst)
			{
				writeBackup();
			}
			writeWorkingFile(json);
		});
	}

	/** Reads a file the user picked. Runs on the worker; the result comes back on the EDT. */
	public void readImportFile(File file, Consumer<LocationReadResult> onResult)
	{
		submit(() ->
		{
			LocationReadResult result = readFile(file);
			SwingUtilities.invokeLater(() -> onResult.accept(result));
		});
	}

	/** Writes a file the user picked. The outcome message comes back on the EDT. */
	public void writeExportFile(File file, List<SavedLocation> toExport,
		Consumer<String> onError)
	{
		final String json = codec.write(toExport);
		submit(() ->
		{
			String error = null;
			try
			{
				Files.write(file.toPath(), json.getBytes(StandardCharsets.UTF_8));
			}
			catch (IOException e)
			{
				log.warn("World Grid could not export locations", e);
				error = e.getMessage();
			}

			final String reported = error;
			SwingUtilities.invokeLater(() -> onError.accept(reported));
		});
	}

	private void submit(Runnable task)
	{
		ExecutorService current = executor;
		if (current == null)
		{
			return;
		}

		try
		{
			current.submit(task);
		}
		catch (RejectedExecutionException e)
		{
			// The plugin was stopped between reading the executor and submitting. A
			// file chooser callback can arrive long after the user turned the plugin
			// off, so this is reachable in normal use, not just at shutdown.
			log.debug("Dropped a locations task because the plugin is stopping", e);
		}
	}

	private void notifyListeners()
	{
		for (Runnable listener : listeners)
		{
			listener.run();
		}
	}

	private void readWorkingFile()
	{
		if (!workingFile.exists())
		{
			// A first run is not an error -- there is simply nothing saved yet.
			return;
		}

		LocationReadResult result = readFile(workingFile);
		SwingUtilities.invokeLater(() ->
		{
			if (result.isSuccess())
			{
				loadError = null;
				locations = Collections.unmodifiableList(result.getLocations());
			}
			else
			{
				// The file is left untouched so the user can inspect or repair it.
				loadError = result.getError();
				log.warn("World Grid could not read {}: {}", workingFile, result.getError());
			}
			notifyListeners();
		});
	}

	private LocationReadResult readFile(File file)
	{
		try
		{
			byte[] bytes = Files.readAllBytes(file.toPath());
			return codec.read(new String(bytes, StandardCharsets.UTF_8));
		}
		catch (IOException e)
		{
			log.warn("World Grid could not read {}", file, e);
			return LocationReadResult.failure("The file could not be read: " + e.getMessage());
		}
	}

	private void writeWorkingFile(String json)
	{
		try
		{
			if (!directory.exists() && !directory.mkdirs())
			{
				log.warn("World Grid could not create {}", directory);
				return;
			}
			Files.write(workingFile.toPath(), json.getBytes(StandardCharsets.UTF_8));
		}
		catch (IOException e)
		{
			log.warn("World Grid could not save locations", e);
		}
	}

	/** Timestamped copy of the file as it stands, taken before anything destructive. */
	void writeBackup()
	{
		if (!workingFile.exists())
		{
			return;
		}

		String name = LocationEdits.backupFileName(Instant.now(), ZoneId.systemDefault());
		try
		{
			Files.copy(workingFile.toPath(), new File(directory, name).toPath());
			log.debug("World Grid wrote backup {}", name);
		}
		catch (IOException e)
		{
			log.warn("World Grid could not write a backup", e);
		}
	}
}

package nz.tate.worldgrid;

import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import nz.tate.worldgrid.core.SavedLocation;

/**
 * Every edit the panel can make to the saved list, as plain list-in list-out functions.
 *
 * <p>Swing and the client cannot be unit tested, so the decisions live here instead of
 * inside a button handler. Nothing in this class imports RuneLite or touches disk.
 *
 * <p>Rows are addressed by their coordinate rather than by object identity, because a
 * pin toggle replaces the entry object while still meaning the same place.
 */
public final class LocationEdits
{
	/** Above this many rows, a bulk delete asks first. */
	public static final int MAX_DELETE_WITHOUT_CONFIRMATION = 3;

	/** Longest label the codec will accept back off disk. */
	public static final int MAX_LABEL_LENGTH = 100;

	private static final DateTimeFormatter BACKUP_STAMP =
		DateTimeFormatter.ofPattern("yyyyMMdd-HHmmss");

	private LocationEdits()
	{
	}

	/**
	 * Tidies a name typed by the user.
	 *
	 * @return the name to store, or null when nothing usable was typed
	 */
	public static String cleanLabel(String typed)
	{
		if (typed == null)
		{
			return null;
		}

		String trimmed = typed.trim();
		if (trimmed.isEmpty())
		{
			return null;
		}
		if (trimmed.length() > MAX_LABEL_LENGTH)
		{
			// Truncating keeps the entry; rejecting it would throw the location away.
			return trimmed.substring(0, MAX_LABEL_LENGTH);
		}
		return trimmed;
	}

	/** Stable identity of a place: the coordinate, never the label. */
	public static String placeKey(SavedLocation location)
	{
		return location.getX() + "," + location.getY() + "," + location.getPlane();
	}

	public static List<SavedLocation> withAdded(List<SavedLocation> locations, SavedLocation added)
	{
		List<SavedLocation> result = new ArrayList<>(locations);
		result.add(added);
		return Collections.unmodifiableList(result);
	}

	public static List<SavedLocation> withoutKeys(List<SavedLocation> locations, Set<String> keys)
	{
		List<SavedLocation> result = new ArrayList<>();
		for (SavedLocation location : locations)
		{
			if (!keys.contains(placeKey(location)))
			{
				result.add(location);
			}
		}
		return Collections.unmodifiableList(result);
	}

	public static List<SavedLocation> withPinnedKey(List<SavedLocation> locations, String key,
		boolean pinned)
	{
		List<SavedLocation> result = new ArrayList<>();
		for (SavedLocation location : locations)
		{
			if (placeKey(location).equals(key))
			{
				result.add(location.withPinned(pinned));
			}
			else
			{
				result.add(location);
			}
		}
		return Collections.unmodifiableList(result);
	}

	public static List<SavedLocation> pinnedOnly(List<SavedLocation> locations)
	{
		List<SavedLocation> result = new ArrayList<>();
		for (SavedLocation location : locations)
		{
			if (location.isPinned())
			{
				result.add(location);
			}
		}
		return Collections.unmodifiableList(result);
	}

	/** What an export writes: the whole list, or only the pinned subset. */
	public static List<SavedLocation> forExport(List<SavedLocation> locations, boolean pinnedOnly)
	{
		if (pinnedOnly)
		{
			return pinnedOnly(locations);
		}
		return Collections.unmodifiableList(new ArrayList<>(locations));
	}

	public static int countPinned(List<SavedLocation> locations)
	{
		return pinnedOnly(locations).size();
	}

	public static boolean containsKey(List<SavedLocation> locations, String key)
	{
		for (SavedLocation location : locations)
		{
			if (placeKey(location).equals(key))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Drops selected rows that are no longer in the list. Selection is transient view
	 * state, so it must not keep pointing at places that have gone.
	 */
	public static Set<String> retainExisting(Set<String> keys, List<SavedLocation> locations)
	{
		Set<String> present = new LinkedHashSet<>();
		for (SavedLocation location : locations)
		{
			String key = placeKey(location);
			if (keys.contains(key))
			{
				present.add(key);
			}
		}
		return present;
	}

	public static Set<String> allKeys(List<SavedLocation> locations)
	{
		Set<String> keys = new LinkedHashSet<>();
		for (SavedLocation location : locations)
		{
			keys.add(placeKey(location));
		}
		return keys;
	}

	/**
	 * Deleting a couple of rows you just ticked is unsurprising; clearing out a dozen is
	 * the mis-click worth stopping. A backup is written either way.
	 */
	public static boolean needsDeleteConfirmation(int count)
	{
		return count > MAX_DELETE_WITHOUT_CONFIRMATION;
	}

	/**
	 * Name of the safety copy written before anything destructive. The timestamp keeps
	 * successive backups from overwriting each other, so recovery works the same however
	 * the data was lost.
	 */
	public static String backupFileName(Instant when, ZoneId zone)
	{
		return "locations.backup-" + BACKUP_STAMP.format(when.atZone(zone)) + ".json";
	}
}

package nz.tate.worldgrid.core;

/**
 * Converts between world coordinates and grid cells.
 *
 * <p>Every division here uses {@link Math#floorDiv}. Plain integer division truncates
 * toward zero, which folds the two squares either side of the anchor into one and
 * produces a wrong cell for anything west or south of it. Bit masking is also wrong:
 * it only works for power-of-two sizes, and DECISIONS D2 allows any size from 1 to 256.
 */
public final class GridMath
{
	private GridMath()
	{
	}

	public static GridCell toCell(int worldX, int worldY, int plane, int gridSize)
	{
		int column = Math.floorDiv(worldX - GridAnchor.ANCHOR_X, gridSize);
		int row = Math.floorDiv(worldY - GridAnchor.ANCHOR_Y, gridSize);
		return new GridCell(column, row, plane);
	}

	/** West edge of the cell, in world coordinates. */
	public static int originX(GridCell cell, int gridSize)
	{
		return GridAnchor.ANCHOR_X + cell.getColumn() * gridSize;
	}

	/** South edge of the cell, in world coordinates. */
	public static int originY(GridCell cell, int gridSize)
	{
		return GridAnchor.ANCHOR_Y + cell.getRow() * gridSize;
	}

	/**
	 * Centre of the cell, rounded down. Used when a searched reference has to become a
	 * single point, since a reference names a square rather than a tile.
	 */
	public static int centreX(GridCell cell, int gridSize)
	{
		return originX(cell, gridSize) + gridSize / 2;
	}

	public static int centreY(GridCell cell, int gridSize)
	{
		return originY(cell, gridSize) + gridSize / 2;
	}

	/**
	 * Lowest grid boundary at or after {@code from}. Used by both overlays to find
	 * where to start drawing lines across the visible area.
	 */
	public static int firstBoundaryAtOrAfter(int from, int anchor, int gridSize)
	{
		int index = Math.floorDiv(from - anchor, gridSize);
		int boundary = anchor + index * gridSize;
		return boundary < from ? boundary + gridSize : boundary;
	}

	public static boolean isValidGridSize(int gridSize)
	{
		return gridSize >= GridAnchor.MIN_GRID_SIZE && gridSize <= GridAnchor.MAX_GRID_SIZE;
	}
}

