package nz.tate.worldgrid.core;

import java.util.ArrayList;
import java.util.List;

/**
 * Works out what an import would produce, without applying it.
 *
 * <p>Merge is purely additive: it never changes an existing entry, so it needs no
 * backup and is safe to offer as the common case. Replace discards everything, so the
 * caller must write a backup first.
 *
 * <p>Imported entries always arrive unpinned. Pinning is a statement about the viewer's
 * current session rather than a property of the place, so a shared file can never light
 * up someone else's map.
 */
public final class ImportPlan
{
	public enum Mode
	{
		MERGE,
		REPLACE
	}

	private final List<SavedLocation> result;
	private final int addedCount;
	private final int skippedCount;
	private final int discardedCount;
	private final Mode mode;

	private ImportPlan(List<SavedLocation> result, int addedCount, int skippedCount,
		int discardedCount, Mode mode)
	{
		this.result = result;
		this.addedCount = addedCount;
		this.skippedCount = skippedCount;
		this.discardedCount = discardedCount;
		this.mode = mode;
	}

	public static ImportPlan create(List<SavedLocation> existing, List<SavedLocation> incoming,
		Mode mode)
	{
		if (mode == Mode.REPLACE)
		{
			return createReplace(existing, incoming);
		}
		return createMerge(existing, incoming);
	}

	private static ImportPlan createReplace(List<SavedLocation> existing,
		List<SavedLocation> incoming)
	{
		List<SavedLocation> result = new ArrayList<>();
		for (SavedLocation location : incoming)
		{
			result.add(location.withPinned(false));
		}
		return new ImportPlan(result, incoming.size(), 0, existing.size(), Mode.REPLACE);
	}

	private static ImportPlan createMerge(List<SavedLocation> existing,
		List<SavedLocation> incoming)
	{
		List<SavedLocation> result = new ArrayList<>(existing);
		int added = 0;
		int skipped = 0;

		for (SavedLocation candidate : incoming)
		{
			if (containsPlace(result, candidate))
			{
				// The existing entry wins, name and all. Merge promised to keep yours.
				skipped++;
			}
			else
			{
				result.add(candidate.withPinned(false));
				added++;
			}
		}
		return new ImportPlan(result, added, skipped, 0, Mode.MERGE);
	}

	private static boolean containsPlace(List<SavedLocation> locations, SavedLocation candidate)
	{
		for (SavedLocation location : locations)
		{
			if (location.isSamePlaceAs(candidate))
			{
				return true;
			}
		}
		return false;
	}

	public List<SavedLocation> getResult()
	{
		return result;
	}

	public int getAddedCount()
	{
		return addedCount;
	}

	/** Incoming entries that were already present. Merge only. */
	public int getSkippedCount()
	{
		return skippedCount;
	}

	/** Existing entries that Replace would throw away. Replace only. */
	public int getDiscardedCount()
	{
		return discardedCount;
	}

	public Mode getMode()
	{
		return mode;
	}

	/**
	 * An import where everything collided otherwise looks like a silent no-op, so the
	 * outcome is always reported.
	 */
	public String describeOutcome()
	{
		if (mode == Mode.REPLACE)
		{
			return "Replaced " + discardedCount + " with " + addedCount + " imported.";
		}
		if (skippedCount == 0)
		{
			return "Imported " + addedCount + " new.";
		}
		return "Imported " + addedCount + " new, skipped " + skippedCount + " already present.";
	}
}

package nz.tate.worldgrid.core;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import java.util.ArrayList;
import java.util.List;

/**
 * Reads and writes the locations file.
 *
 * <p>Every file is validated in full before any of it is used. A file that fails
 * validation is rejected outright, so a bad import can never half-apply or wipe what the
 * user already had.
 */
public final class LocationCodec
{
	/** Above this many entries an import warns before proceeding. Not a hard cap. */
	public static final int LARGE_FILE_WARNING_THRESHOLD = 200;

	private static final int MAX_LABEL_LENGTH = 100;

	private final Gson gson;

	public LocationCodec(Gson gson)
	{
		this.gson = gson;
	}

	public String write(List<SavedLocation> locations)
	{
		return gson.toJson(new LocationFile(LocationFile.CURRENT_VERSION, locations));
	}

	/**
	 * @return the locations exactly as written in the file. Callers decide what to do
	 * with the pinned flag; the import path clears it, loading our own file keeps it.
	 */
	public LocationReadResult read(String json)
	{
		if (json == null || json.trim().isEmpty())
		{
			return LocationReadResult.failure("The file is empty.");
		}

		LocationFile file;
		try
		{
			file = gson.fromJson(json, LocationFile.class);
		}
		catch (JsonSyntaxException e)
		{
			return LocationReadResult.failure("The file is not valid JSON.");
		}

		if (file == null)
		{
			return LocationReadResult.failure("The file is empty.");
		}

		if (file.getVersion() > LocationFile.CURRENT_VERSION)
		{
			return LocationReadResult.failure(
				"This file was written by a newer version of the plugin.");
		}

		List<SavedLocation> validated = new ArrayList<>();
		int index = 0;
		for (SavedLocation location : file.getLocations())
		{
			index++;
			String problem = validate(location);
			if (problem != null)
			{
				return LocationReadResult.failure("Location " + index + " is invalid: " + problem);
			}
			validated.add(location);
		}
		return LocationReadResult.success(validated);
	}

	/**
	 * @return null when the location is usable, otherwise a reason to show the user
	 */
	private String validate(SavedLocation location)
	{
		if (location == null)
		{
			return "it is missing";
		}
		if (location.getLabel() == null || location.getLabel().trim().isEmpty())
		{
			return "it has no name";
		}
		if (location.getLabel().length() > MAX_LABEL_LENGTH)
		{
			return "its name is too long";
		}
		if (location.getX() < 0 || location.getX() > GridAnchor.WORLD_MAX)
		{
			return "its x coordinate is outside the world";
		}
		if (location.getY() < 0 || location.getY() > GridAnchor.WORLD_MAX)
		{
			return "its y coordinate is outside the world";
		}
		if (location.getPlane() < 0 || location.getPlane() > 3)
		{
			return "its plane is not between 0 and 3";
		}
		return null;
	}

	public static boolean isLargeImport(int incomingCount)
	{
		return incomingCount > LARGE_FILE_WARNING_THRESHOLD;
	}
}

package nz.tate.worldgrid.core;

import java.util.Objects;

/**
 * One saved place.
 *
 * <p>Stores the raw world coordinate, never the grid reference. The reference is a
 * display layer over a location rather than the location itself, so recomputing it from
 * the viewer's own grid size means a shared file always points at the right physical
 * place whatever size either player runs.
 *
 * <p>Field names are part of the on-disk format and cannot be renamed.
 */
public final class SavedLocation
{
	private final String label;
	private final int x;
	private final int y;
	private final int plane;
	private final boolean pinned;

	public SavedLocation(String label, int x, int y, int plane, boolean pinned)
	{
		this.label = label;
		this.x = x;
		this.y = y;
		this.plane = plane;
		this.pinned = pinned;
	}

	public String getLabel()
	{
		return label;
	}

	public int getX()
	{
		return x;
	}

	public int getY()
	{
		return y;
	}

	public int getPlane()
	{
		return plane;
	}

	public boolean isPinned()
	{
		return pinned;
	}

	public SavedLocation withPinned(boolean newPinned)
	{
		return new SavedLocation(label, x, y, plane, newPinned);
	}

	/**
	 * Two entries at the same tile are the same place regardless of what each calls it,
	 * so identity is the coordinate and the label is only a name for it.
	 */
	public boolean isSamePlaceAs(SavedLocation other)
	{
		return x == other.x && y == other.y && plane == other.plane;
	}

	@Override
	public boolean equals(Object other)
	{
		if (this == other)
		{
			return true;
		}
		if (!(other instanceof SavedLocation))
		{
			return false;
		}
		SavedLocation that = (SavedLocation) other;
		return x == that.x
			&& y == that.y
			&& plane == that.plane
			&& pinned == that.pinned
			&& Objects.equals(label, that.label);
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(label, x, y, plane, pinned);
	}

	@Override
	public String toString()
	{
		return "SavedLocation(" + label + " @ " + x + "," + y + "," + plane + ", pinned=" + pinned + ")";
	}
}

package nz.tate.worldgrid.core;

/**
 * Renders a cell as the reference players say out loud, such as {@code L35} or
 * {@code GA12+2}.
 *
 * <p>Letters encode the row and increase going north, so row A is southernmost.
 * Numbers encode the column and increase going east. Planes above ground are appended
 * as {@code +1} to {@code +3}; ground level has no suffix.
 */
public final class GridRefFormatter
{
	private static final int ALPHABET_SIZE = 26;

	private GridRefFormatter()
	{
	}

	/**
	 * @return the reference, or null if the cell sits outside the grid
	 */
	public static String format(GridCell cell)
	{
		if (cell.isNegative())
		{
			return null;
		}

		StringBuilder reference = new StringBuilder();
		reference.append(toLetters(cell.getRow()));
		reference.append(cell.getColumn() + 1);

		if (cell.getPlane() > 0)
		{
			reference.append('+').append(cell.getPlane());
		}
		return reference.toString();
	}

	/**
	 * Converts a zero-based row index to spreadsheet-style letters: 0 is A, 25 is Z,
	 * 26 is AA. Counting starts at one internally because the sequence has no zero
	 * digit, the same way spreadsheet columns work.
	 */
	public static String toLetters(int rowIndex)
	{
		if (rowIndex < 0)
		{
			throw new IllegalArgumentException("Row index cannot be negative: " + rowIndex);
		}

		StringBuilder letters = new StringBuilder();
		int remaining = rowIndex + 1;

		while (remaining > 0)
		{
			int digit = (remaining - 1) % ALPHABET_SIZE;
			letters.append((char) ('A' + digit));
			remaining = (remaining - 1) / ALPHABET_SIZE;
		}
		return letters.reverse().toString();
	}

	/** Inverse of {@link #toLetters(int)}. Input must already be upper case. */
	public static int fromLetters(String letters)
	{
		int index = 0;
		for (int i = 0; i < letters.length(); i++)
		{
			index = index * ALPHABET_SIZE + (letters.charAt(i) - 'A' + 1);
		}
		return index - 1;
	}
}

