import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.MenuOpened;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.worldmap.WorldMap;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.chatbox.ChatboxPanelManager;
import net.runelite.client.ui.JagexColors;
import net.runelite.client.ui.overlay.worldmap.WorldMapPointManager;
import net.runelite.client.util.ColorUtil;
import nz.tate.worldgrid.core.GridCell;
import nz.tate.worldgrid.core.GridMath;
import nz.tate.worldgrid.core.GridRefParseResult;
import nz.tate.worldgrid.core.GridRefParser;
import nz.tate.worldgrid.core.SavedLocation;

/**
 * "Search grid ref" on the world map's right-click menu.
 *
 * <p>The entry is a {@link MenuAction#RUNELITE} entry, which is client-side only and
 * sends nothing to the server -- the same mechanism core RuneLite's own "Focus on" uses.
 *
 * <p>There is at most one search pin at a time: a second search moves the existing one
 * rather than adding another, so "Remove pin" is never ambiguous and a session of
 * searching does not litter the map.
 *
 * <p>The menu callbacks and the chatbox prompt both run on the client thread. Only
 * saving crosses over: the list is edited on the Swing thread, and the confirmation
 * comes back to chat through {@link ClientThread}.
 */
@Slf4j
@Singleton
public class GridSearch
{
	private static final String SEARCH_OPTION = "Search";
	private static final String SEARCH_TARGET = "grid ref";
	private static final String SAVE_OPTION = "Save location";
	private static final String REMOVE_OPTION = "Remove pin";

	private final Client client;
	private final ChatboxPanelManager chatboxPanelManager;
	private final WorldMapPointManager worldMapPointManager;
	private final WorldGridConfig config;
	private final LocationRepository repository;
	private final ClientThread clientThread;

	private SearchMapPoint searchPin;

	@Inject
	GridSearch(Client client, ChatboxPanelManager chatboxPanelManager,
		WorldMapPointManager worldMapPointManager, WorldGridConfig config,
		LocationRepository repository, ClientThread clientThread)
	{
		this.client = client;
		this.chatboxPanelManager = chatboxPanelManager;
		this.worldMapPointManager = worldMapPointManager;
		this.config = config;
		this.repository = repository;
		this.clientThread = clientThread;
	}

	public void shutDown()
	{
		searchPin = null;
	}

	@Subscribe
	public void onMenuOpened(MenuOpened event)
	{
		if (!isMouseOverWorldMap())
		{
			return;
		}

		if (searchPin != null)
		{
			// Offered on the map rather than only on the pin itself, so a pin that has
			// snapped to the edge of the view is still reachable.
			final SearchMapPoint pin = searchPin;
			client.createMenuEntry(-1)
				.setOption(REMOVE_OPTION)
				.setTarget(target(pin.getName()))
				.setType(MenuAction.RUNELITE)
				.onClick(entry -> removePin());

			client.createMenuEntry(-1)
				.setOption(SAVE_OPTION)
				.setTarget(target(pin.getName()))
				.setType(MenuAction.RUNELITE)
				.onClick(entry -> promptForName(pin.getWorldPoint()));
		}

		client.createMenuEntry(-1)
			.setOption(SEARCH_OPTION)
			.setTarget(target(SEARCH_TARGET))
			.setType(MenuAction.RUNELITE)
			.onClick(entry -> openPrompt());
	}

	private static String target(String text)
	{
		return ColorUtil.wrapWithColorTag(text, JagexColors.MENU_TARGET);
	}

	private boolean isMouseOverWorldMap()
	{
		Widget mapView = client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER);
		if (mapView == null || mapView.isHidden())
		{
			return false;
		}

		Rectangle bounds = mapView.getBounds();
		Point mouse = client.getMouseCanvasPosition();
		return bounds != null && mouse != null && bounds.contains(mouse.getX(), mouse.getY());
	}

	private void openPrompt()
	{
		Consumer<String> onDone = this::search;
		chatboxPanelManager.openTextInput("Grid ref:")
			// Only the characters a reference can contain, so a malformed one is hard to
			// type in the first place.
			.addCharValidator(typed -> Character.isLetterOrDigit(typed) || typed == '+')
			.onDone(onDone)
			.build();
	}

	private void search(String typed)
	{
		int gridSize = config.gridSize();
		GridRefParseResult result = GridRefParser.parse(typed, gridSize);
		if (!result.isSuccess())
		{
			message(result.getMessage());
			return;
		}

		GridCell cell = result.getCell();
		// A reference names a square, so the pin goes to the middle of it.
		WorldPoint target = new WorldPoint(
			GridMath.centreX(cell, gridSize),
			GridMath.centreY(cell, gridSize),
			cell.getPlane());

		WorldMap worldMap = client.getWorldMap();
		if (worldMap != null)
		{
			worldMap.setWorldMapPositionTarget(target);
		}

		dropPin(typed.trim().toUpperCase(), target);
	}

	private void dropPin(String reference, WorldPoint target)
	{
		worldMapPointManager.removeIf(point -> point instanceof SearchMapPoint);

		searchPin = new SearchMapPoint(target);
		searchPin.setName(reference);
		searchPin.setTooltip(reference + " (searched)");
		searchPin.setTarget(target);
		searchPin.setJumpOnClick(true);
		searchPin.setSnapToEdge(true);
		worldMapPointManager.add(searchPin);
	}

	private void removePin()
	{
		worldMapPointManager.removeIf(point -> point instanceof SearchMapPoint);
		searchPin = null;
	}

	/**
	 * Promotes a searched reference into the saved list. Without this the only route to
	 * a saved entry would be to travel to the place and press save, which defeats the
	 * point of searching for somewhere you are not.
	 */
	private void promptForName(WorldPoint point)
	{
		Consumer<String> onDone = typed -> saveSearched(typed, point);
		chatboxPanelManager.openTextInput("Name:")
			.addCharValidator(typed -> typed >= ' ' && typed <= '~')
			.onDone(onDone)
			.build();
	}

	private void saveSearched(String typed, WorldPoint point)
	{
		String label = LocationEdits.cleanLabel(typed);
		if (label == null)
		{
			message("A location needs a name.");
			return;
		}

		// Saving from a search stores the square's centre tile, which is coarser than
		// save-current-location's exact tile. Both are valid places.
		SavedLocation saved = new SavedLocation(
			label, point.getX(), point.getY(), point.getPlane(), false);

		// The repository is edited from the Swing thread; the file write is its own job.
		SwingUtilities.invokeLater(() ->
		{
			if (LocationEdits.containsKey(repository.getLocations(),
				LocationEdits.placeKey(saved)))
			{
				report("That square is already saved.");
				return;
			}

			repository.replaceAll(
				LocationEdits.withAdded(repository.getLocations(), saved), false);
			report("Saved " + label + ".");
		});
	}

	/** Chat messages belong to the client thread, and this is called from Swing. */
	private void report(String text)
	{
		clientThread.invoke(() -> message(text));
	}

	private void message(String text)
	{
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", "World Grid: " + text, null);
	}
}

package nz.tate.worldgrid;

import java.awt.image.BufferedImage;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.worldmap.WorldMapPoint;

/**
 * Base class for every pin this plugin puts on the world map.
 *
 * <p>It exists so shutting the plugin down can clear exactly our own pins with a single
 * {@code removeIf}, without disturbing any other plugin's. A leaked pin otherwise stays
 * on the map until the client restarts.
 */
public abstract class WorldGridMapPoint extends WorldMapPoint
{
	WorldGridMapPoint(WorldPoint worldPoint, BufferedImage image)
	{
		super(worldPoint, image);
	}
}

package nz.tate.worldgrid;

import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.ui.overlay.worldmap.WorldMapPointManager;
import nz.tate.worldgrid.core.SavedLocation;

/**
 * Puts a world map pin on every saved location the user has lit up.
 *
 * <p>The list is your library; the pinned subset is what appears on the map. That is
 * what keeps a forty-entry imported clan file from carpeting the world map.
 *
 * <p>Toggles arrive on the Swing event thread and {@link WorldMapPointManager} belongs
 * to the client, so every change is marshalled with {@link ClientThread#invoke}.
 */
@Singleton
public class PinManager
{
	private final ClientThread clientThread;
	private final WorldMapPointManager worldMapPointManager;
	private final WorldGridConfig config;
	private final LocationRepository repository;

	@Inject
	PinManager(ClientThread clientThread, WorldMapPointManager worldMapPointManager,
		WorldGridConfig config, LocationRepository repository)
	{
		this.clientThread = clientThread;
		this.worldMapPointManager = worldMapPointManager;
		this.config = config;
		this.repository = repository;

		repository.addListener(this::refresh);
	}

	public void shutDown()
	{
		// Clears the searched pin as well as the saved ones, and nobody else's.
		clientThread.invoke(() ->
			worldMapPointManager.removeIf(point -> point instanceof WorldGridMapPoint));
	}

	/**
	 * Rebuilds the saved pins from the current list. Only ever runs on a user action,
	 * never per frame, so rebuilding the handful of pinned entries is cheaper than
	 * working out which ones changed.
	 */
	public void refresh()
	{
		final List<SavedLocation> pinned = LocationEdits.pinnedOnly(repository.getLocations());
		final int gridSize = config.gridSize();

		clientThread.invoke(() ->
		{
			worldMapPointManager.removeIf(point -> point instanceof SavedLocationMapPoint);
			for (SavedLocation location : pinned)
			{
				worldMapPointManager.add(build(location, gridSize));
			}
		});
	}

	private SavedLocationMapPoint build(SavedLocation location, int gridSize)
	{
		WorldPoint worldPoint =
			new WorldPoint(location.getX(), location.getY(), location.getPlane());

		SavedLocationMapPoint point = new SavedLocationMapPoint(worldPoint, PinIcons.SAVED);
		point.setName(location.getLabel());
		point.setTooltip(LocationDisplay.tooltip(location, gridSize));
		point.setTarget(worldPoint);
		point.setJumpOnClick(true);
		// An off-screen pin clings to the edge of the map pointing towards itself, which
		// is what you want when someone reads out a place on the far side of the world.
		point.setSnapToEdge(true);
		return point;
	}
}

package nz.tate.worldgrid;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

/**
 * Config keys are permanent. Renaming one silently resets everybody's settings, so these
 * names cannot change once the plugin has shipped.
 */
@ConfigGroup(WorldGridConfig.GROUP)
public interface WorldGridConfig extends Config
{
	String GROUP = "world-grid";

	@ConfigSection(
		name = "Grid",
		description = "Size and where the grid is drawn",
		position = 0
	)
	String gridSection = "gridSection";

	@ConfigSection(
		name = "Appearance",
		description = "Colour and line thickness",
		position = 1
	)
	String appearanceSection = "appearanceSection";

	@Range(min = 1, max = 256)
	@ConfigItem(
		keyName = "gridSize",
		name = "Grid size",
		description = "Width of one square in tiles. Both players must use the same size"
			+ " for spoken references to agree.",
		position = 0,
		section = gridSection
	)
	default int gridSize()
	{
		return 64;
	}

	@ConfigItem(
		keyName = "drawOnWorldMap",
		name = "Draw grid on world map",
		description = "Overlay the grid on the world map.",
		position = 1,
		section = gridSection
	)
	default boolean drawOnWorldMap()
	{
		return true;
	}

	@ConfigItem(
		keyName = "drawInScene",
		name = "Draw grid in scene",
		description = "Overlay the grid on the game world, and label the square you are"
			+ " standing on.",
		position = 2,
		section = gridSection
	)
	default boolean drawInScene()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showRefReadout",
		name = "Show grid reference readout",
		description = "Show a movable readout of your current grid reference. Works with"
			+ " both grid overlays turned off.",
		position = 3,
		section = gridSection
	)
	default boolean showRefReadout()
	{
		return true;
	}

	/** Remembered so an exported file lands where the last one did. Not user-facing. */
	@ConfigItem(
		keyName = "lastFileDirectory",
		name = "Last import/export folder",
		description = "Remembered folder for import and export.",
		hidden = true
	)
	default String lastFileDirectory()
	{
		return "";
	}

	@Alpha
	@ConfigItem(
		keyName = "gridColour",
		name = "Grid colour",
		description = "Colour of the grid lines and labels.",
		position = 0,
		section = appearanceSection
	)
	default Color gridColour()
	{
		return new Color(255, 255, 255, 100);
	}

	@Range(min = 1, max = 5)
	@ConfigItem(
		keyName = "lineThickness",
		name = "Line thickness",
		description = "Thickness of the grid lines in pixels.",
		position = 1,
		section = appearanceSection
	)
	default int lineThickness()
	{
		return 1;
	}
}
